// Administrative history-only registration. All components are preflighted;
// newly created steps commit disabled, and activation is a separate operation.
using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Security.Cryptography;
using Microsoft.Crm.Sdk.Messages;
using Microsoft.Xrm.Sdk;
using Microsoft.Xrm.Sdk.Query;
using Newtonsoft.Json;
using Oiac.Engage.SiteActivityLog;
public static class RegisterSiteActivityLogPortalPlan {
 const string Prefix="Oiac.Engage.SiteActivityLog.",Capture=Prefix+"SiteActivityLogLegacyCapturePlugin",Stamp=Prefix+"SiteActivityLogCoverageProvenancePlugin";
 static readonly Guid Org=new Guid("3f613eb3-72ea-f011-aa23-6045bd003f09"),PortalUser=new Guid("605697c5-69a5-f111-b8dd-002248042536");
 public sealed class TypePlan{public Guid Id;public string Name;public bool Create;}
 public sealed class ImagePlan{public Guid Id;public string Alias,Fields,Property;public int Kind;public bool Create;}
 public sealed class StepPlan{public Guid Id,Type,MessageId,Filter;public string Name,Table,Message,Handler,Fields,Configuration;public int Stage,Mode,Rank,State;public bool Create;public List<ImagePlan> Images=new List<ImagePlan>();}
 public sealed class Journal{public int Schema=1;public Guid Organization,Assembly,VerifiedPortalUser;public string RuntimeHash,Operation;public List<TypePlan> Types;public List<StepPlan> Steps;}
 static void Need(bool v,string message){if(!v)throw new InvalidOperationException(message);}
 static int Choice(Entity e,string k){var v=e.GetAttributeValue<OptionSetValue>(k);return v==null?-1:v.Value;}
 static Guid Ref(Entity e,string k){var v=e.GetAttributeValue<EntityReference>(k);return v==null?Guid.Empty:v.Id;}
 static string Hash(byte[] bytes){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}
 static string Csv(string text){return string.Join(",",(text??"").Split(new[]{','},StringSplitOptions.RemoveEmptyEntries).OrderBy(v=>v,StringComparer.Ordinal));}
 static Entity[] Query(IOrganizationService s,string table,params object[] fields){var q=new QueryExpression(table){ColumnSet=new ColumnSet(true)};for(int i=0;i<fields.Length;i+=2)q.Criteria.AddCondition((string)fields[i],ConditionOperator.Equal,fields[i+1]);return s.RetrieveMultiple(q).Entities.ToArray();}
 static Entity Find(IOrganizationService s,string table,params object[] fields){var rows=Query(s,table,fields);Need(rows.Length<=1,"Ambiguous history component: "+table);return rows.SingleOrDefault();}
 static string Runtime(IOrganizationService s,Guid assembly){Need(((WhoAmIResponse)s.Execute(new WhoAmIRequest())).OrganizationId==Org,"Exact OIAC UAT required.");var local=typeof(SiteActivityLogCoverageProvenancePlugin).Assembly;string expected=Hash(File.ReadAllBytes(local.Location));var row=s.Retrieve("pluginassembly",assembly,new ColumnSet("name","version","publickeytoken","isolationmode","sourcetype","content"));Need(assembly!=Guid.Empty&&row.Id==assembly&&row.GetAttributeValue<string>("name")=="Oiac.Engage.SiteActivityLog"&&row.GetAttributeValue<string>("version")=="1.0.0.0"&&row.GetAttributeValue<string>("publickeytoken")=="2f0fd985deb9be5f"&&Choice(row,"isolationmode")==2&&Choice(row,"sourcetype")==0&&Hash(Convert.FromBase64String(row.GetAttributeValue<string>("content")))==expected,"Deploy exact reviewed signed history runtime first.");var user=s.Retrieve("systemuser",PortalUser,new ColumnSet("applicationid"));Need(user.Id==PortalUser&&user.GetAttributeValue<Guid>("applicationid")!=Guid.Empty,"Verified portal application identity differs.");return expected;}
 static List<StepPlan> Specs(){var specs=new List<StepPlan>();string config="integrationUser="+PortalUser.ToString("D")+";organization="+Org.ToString("D");foreach(string table in new[]{"mss_meetingreport","mss_events","mss_eventregistration","contact","mss_presscoverage"})foreach(string message in new[]{"Create","Update","Delete"}){string fields=string.Join(",",SiteActivityLogLegacyCapturePlugin.FieldsFor(table));var p=new StepPlan{Name="OIAC History Portal "+table+" "+message,Table=table,Message=message,Handler=Capture,Fields=message=="Update"?fields:null,Configuration=config,Stage=40,Mode=1,Rank=100};if(message!="Create")p.Images.Add(new ImagePlan{Alias="PreImage",Kind=0,Fields=fields,Property="Target"});if(message!="Delete")p.Images.Add(new ImagePlan{Alias="PostImage",Kind=1,Fields=fields,Property=message=="Create"?"Id":"Target"});specs.Add(p);}
  var stamp=new StepPlan{Name="OIAC History Coverage Upload Stamp",Table="mss_presscoverage",Message="Update",Handler=Stamp,Fields="mss_coverageuploadstate",Stage=20,Mode=0,Rank=1};stamp.Images.Add(new ImagePlan{Alias="PreImage",Kind=0,Fields="mss_coverageuploadstate",Property="Target"});specs.Add(stamp);return specs;}
 static Journal Plan(IOrganizationService s,Guid assembly,bool activate){string hash=Runtime(s,assembly);var types=new List<TypePlan>();foreach(string name in new[]{Capture,Stamp}){var row=Find(s,"plugintype","typename",name);Need(row==null||Ref(row,"pluginassemblyid")==assembly,"History handler assembly differs.");Need(!activate||row!=null,"Configure disabled history handlers first.");types.Add(new TypePlan{Id=row==null?Guid.NewGuid():row.Id,Name=name,Create=row==null});}
  var steps=Specs();foreach(var p in steps){p.Type=types.Single(t=>t.Name==p.Handler).Id;var message=Find(s,"sdkmessage","name",p.Message);Need(message!=null,"History SDK message missing.");p.MessageId=message.Id;var filter=Find(s,"sdkmessagefilter","sdkmessageid",message.Id,"primaryobjecttypecode",p.Table);Need(filter!=null,"History SDK table filter missing: "+p.Table+" "+p.Message);p.Filter=filter.Id;var row=Find(s,"sdkmessageprocessingstep","name",p.Name);Need(!activate||row!=null,"Configure all disabled history steps first.");p.Id=row==null?Guid.NewGuid():row.Id;p.Create=row==null;p.State=row==null?1:Choice(row,"statecode");
   if(row!=null){Need(Ref(row,"eventhandler")==p.Type&&Ref(row,"sdkmessageid")==p.MessageId&&Ref(row,"sdkmessagefilterid")==p.Filter&&Choice(row,"stage")==p.Stage&&Choice(row,"mode")==p.Mode&&row.GetAttributeValue<int>("rank")==p.Rank&&Choice(row,"supporteddeployment")==0&&!row.GetAttributeValue<bool>("asyncautodelete")&&Ref(row,"impersonatinguserid")==Guid.Empty&&Ref(row,"sdkmessageprocessingstepsecureconfigid")==Guid.Empty&&(row.GetAttributeValue<string>("configuration")??"")==(p.Configuration??"")&&Csv(row.GetAttributeValue<string>("filteringattributes"))==Csv(p.Fields),"Existing history step differs: "+p.Name);Need(p.State==1&&Choice(row,"statuscode")==2||activate&&p.State==0&&Choice(row,"statuscode")==1,"History configuration is disabled-only.");}
   var images=Query(s,"sdkmessageprocessingstepimage","sdkmessageprocessingstepid",p.Id);Need(images.Length<=p.Images.Count&&images.Select(i=>i.GetAttributeValue<string>("name")).Distinct().Count()==images.Length,"Unexpected history image.");foreach(var image in images){var wanted=p.Images.SingleOrDefault(i=>i.Alias==image.GetAttributeValue<string>("name"));Need(wanted!=null&&image.GetAttributeValue<string>("entityalias")==wanted.Alias&&Choice(image,"imagetype")==wanted.Kind&&Csv(image.GetAttributeValue<string>("attributes"))==Csv(wanted.Fields)&&image.GetAttributeValue<string>("messagepropertyname")==wanted.Property&&string.IsNullOrEmpty(image.GetAttributeValue<string>("relatedattributename")),"Existing history image differs.");wanted.Id=image.Id;}foreach(var image in p.Images){image.Create=image.Id==Guid.Empty;if(image.Create)image.Id=Guid.NewGuid();Need(!activate||!image.Create,"Complete history images before activation.");}
  }
  foreach(var type in types.Where(t=>!t.Create))Need(Query(s,"sdkmessageprocessingstep","eventhandler",type.Id).All(row=>steps.Any(p=>!p.Create&&p.Id==row.Id&&p.Type==type.Id)),"Unexpected protected history handler registration.");return new Journal{Organization=Org,Assembly=assembly,VerifiedPortalUser=PortalUser,RuntimeHash=hash,Operation=activate?"activate-portal-history-only":"configure-disabled-portal-history",Types=types,Steps=steps};
 }
 static void Save(string path,Journal plan){Need(!string.IsNullOrWhiteSpace(path)&&!File.Exists(path),"Fresh history registration journal required.");using(var file=new FileStream(path,FileMode.CreateNew,FileAccess.Write,FileShare.None))using(var writer=new StreamWriter(file))writer.Write(JsonConvert.SerializeObject(plan,Formatting.Indented));}
 public static void Configure(IOrganizationService s,Guid assembly,string journal){var p=Plan(s,assembly,false);Save(journal,p);foreach(var type in p.Types.Where(t=>t.Create)){var e=new Entity("plugintype",type.Id);e["typename"]=type.Name;e["name"]=type.Name;e["friendlyname"]=type.Name;e["pluginassemblyid"]=new EntityReference("pluginassembly",assembly);Need(s.Create(e)==type.Id,"Unexpected history handler identity.");}foreach(var step in p.Steps){if(step.Create){var e=new Entity("sdkmessageprocessingstep",step.Id);e["name"]=step.Name;e["eventhandler"]=new EntityReference("plugintype",step.Type);e["sdkmessageid"]=new EntityReference("sdkmessage",step.MessageId);e["sdkmessagefilterid"]=new EntityReference("sdkmessagefilter",step.Filter);e["stage"]=new OptionSetValue(step.Stage);e["mode"]=new OptionSetValue(step.Mode);e["rank"]=step.Rank;e["supporteddeployment"]=new OptionSetValue(0);e["asyncautodelete"]=false;if(step.Configuration!=null)e["configuration"]=step.Configuration;if(step.Fields!=null)e["filteringattributes"]=step.Fields;Need(RegisterSiteActivityLogObservers.CreateDisabledStep(s,e)==step.Id,"Unexpected disabled history step identity.");}foreach(var image in step.Images.Where(i=>i.Create)){var e=new Entity("sdkmessageprocessingstepimage",image.Id);e["name"]=image.Alias;e["entityalias"]=image.Alias;e["imagetype"]=new OptionSetValue(image.Kind);e["attributes"]=image.Fields;e["messagepropertyname"]=image.Property;e["sdkmessageprocessingstepid"]=new EntityReference("sdkmessageprocessingstep",step.Id);Need(s.Create(e)==image.Id,"Unexpected history image identity.");}}Console.WriteLine("Configured fifteen disabled portal observers and one disabled upload provenance stamp; existing business handlers unchanged.");}
 public static void Activate(IOrganizationService s,Guid assembly,string journal){var p=Plan(s,assembly,true);foreach(string message in new[]{"Update","Delete"}){var guard=Find(s,"sdkmessageprocessingstep","name","OIAC History mss_activitylog "+message);Need(guard!=null&&Choice(guard,"stage")==10&&Choice(guard,"mode")==0&&Choice(guard,"statecode")==0&&Choice(guard,"statuscode")==1,"Enable the proven permanent history guards first.");var type=s.Retrieve("plugintype",Ref(guard,"eventhandler"),new ColumnSet("typename","pluginassemblyid"));Need(type.GetAttributeValue<string>("typename")==Prefix+"SiteActivityLogGuardPlugin"&&Ref(type,"pluginassemblyid")==assembly,"History guard handler differs.");}Save(journal,p);foreach(var step in p.Steps.Where(x=>x.State==1).OrderBy(x=>x.Mode))s.Execute(new SetStateRequest{EntityMoniker=new EntityReference("sdkmessageprocessingstep",step.Id),State=new OptionSetValue(0),Status=new OptionSetValue(1)});Console.WriteLine("Activated only the sixteen verified portal-history/upload-provenance steps; business services, permissions and flows unchanged.");}
}
